INSERT INTO RECRUIT (SEQ
                   , NAME
                   , BIRTH
                   , GENDER
                   , PHONE
                   , EMAIL
                   , ADDR
                   , LOCATION
                   , WORK_TYPE
                   , SUBMIT)
 VALUES (
         (SELECT TO_NUMBER(NVL(MAX(SEQ), 0) + 1) FROM RECRUIT)
       , #{name}
       , #{birth}
       , #{gender}
       , #{phone}
       , #{email}
       , #{addr}
       , #{location}
       , #{workType}
       , #{submit}
       )

mapper.update:
	UPDATE RECRUIT
	   SET NAME = #{name}
	     , BIRTH = #{birth}
	     , GENDER = #{gender}
	     , PHONE = #{phone}
	     , EMAIL = #{email}
	     , ADDR = #{addr}
      	 , LOCATION = #{location}
      	 , WORK_TYPE = #{workType}
	     , SUBMIT = #{submit}
	 WHERE SEQ = #{seq}

mapper.insert:
INSERT INTO EDUCATION ( EDU_SEQ , SEQ , SCHOOL_NAME , DIVISION , START_PERIOD , END_PERIOD , MAJOR , GRADE , LOCATION ) SELECT (SELECT NVL(MAX(EDU_SEQ), 0) FROM EDUCATION) + ROWNUM AS EDU_SEQ , A.SEQ , A.SCHOOL_NAME , A.DIVISION , A.START_PERIOD , A.END_PERIOD , A.MAJOR , A.GRADE , A.LOCATION FROM (
SELECT #{education.seq, jdbcType=VARCHAR} AS SEQ , #{education.schoolName, jdbcType=VARCHAR} AS SCHOOL_NAME , #{education.division, jdbcType=VARCHAR} AS DIVISION , #{education.startPeriod, jdbcType=VARCHAR} AS START_PERIOD , #{education.endPeriod, jdbcType=VARCHAR} AS END_PERIOD , #{education.major, jdbcType=VARCHAR} AS MAJOR , #{education.grade, jdbcType=VARCHAR} AS GRADE , #{education.location, jdbcType=VARCHAR} AS LOCATION FROM DUAL
) A

INSERT INTO CAREER ( CAR_SEQ , SEQ , COMP_NAME , LOCATION , START_PERIOD , END_PERIOD , TASK ) SELECT (SELECT NVL(MAX(CAR_SEQ), 0) FROM CAREER) + ROWNUM AS CAR_SEQ , A.SEQ , A.COMP_NAME , A.LOCATION , A.START_PERIOD , A.END_PERIOD , A.TASK FROM (
SELECT #{career.seq, jdbcType=VARCHAR} AS SEQ , #{career.compName, jdbcType=VARCHAR} AS COMP_NAME , #{career.location, jdbcType=VARCHAR} AS LOCATION , #{career.startPeriod, jdbcType=VARCHAR} AS START_PERIOD , #{career.endPeriod, jdbcType=VARCHAR} AS END_PERIOD , #{career.task, jdbcType=VARCHAR} AS TASK FROM DUAL
) A

INSERT INTO CERTIFICATE ( CERT_SEQ , SEQ , QUALIFI_NAME , ACQU_DATE , ORGANIZE_NAME ) SELECT (SELECT NVL(MAX(CERT_SEQ), 0) FROM CERTIFICATE) + ROWNUM AS CERT_SEQ , A.SEQ , A.QUALIFI_NAME , A.ACQU_DATE , A.ORGANIZE_NAME FROM (
SELECT #{certificate.seq, jdbcType=VARCHAR} AS SEQ , #{certificate.qualifiName, jdbcType=VARCHAR} AS QUALIFI_NAME , #{certificate.acquDate, jdbcType=VARCHAR} AS ACQU_DATE , #{certificate.organizeName, jdbcType=VARCHAR} AS ORGANIZE_NAME FROM DUAL
) A
